// chunks splits [from, to] into ranges of at most n days.
func chunks(from, to time.Time, n int) [][2]time.Time {
	var out [][2]time.Time
	for start := from; !start.After(to); start = start.AddDate(0, 0, n) {
		end := start.AddDate(0, 0, n-1)
		if end.After(to) {
			end = to
		}
		out = append(out, [2]time.Time{start, end})
	}
	return out
}

// pause waits Delay between API calls.
func (s *Syncer) pause(ctx context.Context) error {
	if s.Delay <= 0 {
		return nil
	}
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-time.After(s.Delay):
		return nil
	}
}
